            u_xlat3.y = u_xlat9 * 43758.5469;
            u_xlat3.x = dot(u_xlat3.xw, vec2(12.9898005, 78.2330017));
            u_xlat3.x = cos(u_xlat3.x);
            u_xlat3.x = u_xlat3.x * 43758.5469;
            u_xlat15.x = dot(u_xlat4.xy, vec2(12.9898005, 78.2330017));
            u_xlat15.x = cos(u_xlat15.x);
            u_xlat3.z = u_xlat15.x * 43758.5469;
            u_xlat3.xyz = fract(u_xlat3.xyz);
            u_xlat4.xy = fract(u_xlat2.xy);
            u_xlat5.xy = u_xlat4.xy * vec2(-2.0, -2.0) + vec2(3.0, 3.0);
            u_xlat4.xy = u_xlat4.xy * u_xlat4.xy;
            u_xlat4.xy = u_xlat4.xy * u_xlat5.xy;
            u_xlat9 = (-u_xlat16.x) + u_xlat3.y;
            u_xlat9 = u_xlat4.x * u_xlat9 + u_xlat16.x;
            u_xlat15.x = (-u_xlat3.x) + u_xlat3.z;
            u_xlat3.x = u_xlat4.x * u_xlat15.x + u_xlat3.x;
            u_xlat3.x = (-u_xlat9) + u_xlat3.x;
            u_xlat3.x = u_xlat4.y * u_xlat3.x + u_xlat9;
            u_xlat14.x = u_xlat19 * u_xlat3.x + u_xlat14.x;
            u_xlat19 = u_xlat19 * 0.5;
            u_xlat2.xy = u_xlat2.xy + u_xlat2.xy;
            u_xlat20 = u_xlat20 + 1.0;
        }
        u_xlat1.x = u_xlat1.x * u_xlat14.x;
        u_xlat2 = (-_background_color) + _smoke_color;
        u_xlat0 = u_xlat1.xxxx * u_xlat2 + _background_color;
    }
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlatb2.x = int(_blend_mode)==1;
    u_xlat3 = u_xlat0 * u_xlat1;
    u_xlat4.xyz = u_xlat0.xyz + u_xlat1.xyz;
    u_xlat4.w = u_xlat1.w;
    u_xlat2 = (u_xlatb2.x) ? u_xlat3 : u_xlat4;
    u_xlat3.xyz = u_xlat0.xyz;
    u_xlat0 = (int(_blend_mode) != 0) ? u_xlat2 : u_xlat3;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
